// arrays: multi-dimensional, copy functions, fill, sort, binarySearch, array of arrays equality, typed arrays
fun main() {
    val grid = Array(3) { r -> IntArray(3) { c -> r * 3 + c } }; println(grid.joinToString { it.joinToString("") }); grid[1][1] = 99; println(grid[1].toList()); println(grid.sumOf { it.sum() }); println(grid.map { it.max() })
    val a = intArrayOf(5, 3, 9, 1); a.sort(); println(a.toList()); println(a.binarySearch(5)); println(a.binarySearch(4)); a.sortDescending(); println(a.toList()); println(a.reversedArray().toList()); a.fill(7); println(a.toList()); a.fill(0, 1, 3); println(a.toList())
    val b = a.copyOf(6); println(b.toList()); println(a.copyOf(2).toList()); println(a.copyOfRange(1, 3).toList()); println((intArrayOf(1, 2) + 3).toList()); println(a.size); println(a.lastIndex); println(a.isEmpty())
    val s = arrayOf("b", "a", "c"); s.sort(); println(s.toList()); println(s.joinToString("")); s.reverse(); println(s.toList()); println(s.indexOf("a")); println(s.contains("z")); println(s.sortedArray().toList()); println(s.sortedByDescending { it }.toList())
    val d = DoubleArray(3) { it * 0.5 }; println(d.toList()); println(d.sum()); println(d.average()); val bytes = ByteArray(3) { (it * 100).toByte() }; println(bytes.toList()); val cs = charArrayOf('x', 'y'); println(cs.concatToString()); println(String(cs)); println(cs.toList()); val bo = BooleanArray(2); println(bo.toList()); val la = LongArray(2) { it.toLong() shl 40 }; println(la.toList())
    val nested = arrayOf(intArrayOf(1), intArrayOf(2, 3)); println(nested.flatMap { it.toList() }); println(nested.map { it.size }); println(nested.contentDeepToString()); println(arrayOf(arrayOf(1, 2), arrayOf(3)).contentDeepToString()); println(arrayOf(1, 2).contentToString()); println(intArrayOf().contentToString())
    val objs = arrayOfNulls<String>(2); println(objs.contentToString()); val e = emptyArray<Int>(); println(e.size); val arrOfList = Array(2) { mutableListOf(it) }; arrOfList[0].add(5); println(arrOfList.toList()); val m = Array(2) { Array(2) { 0 } }; m[0][1] = 1; println(m.contentDeepToString())
    val sub = arrayOf(1, 2, 3, 4).sliceArray(1..2); println(sub.toList()); println(arrayOf(3, 1, 2).sortedArray().toList()); println(arrayOf(1, 2, 3).sum()); println(arrayOf(1, 2, 3).max()); println(arrayOf("a").plus("b").toList()); println(intArrayOf(3, 4).withIndex().map { it.index * it.value })
    var sw = intArrayOf(1, 2); val t = sw[0]; sw[0] = sw[1]; sw[1] = t; println(sw.toList()); println(arrayOf(1, 2, 3).asList().subList(1, 3)); println(intArrayOf(1, 2, 3).asList()); println(arrayOf(1, 2, 3).reversed()); println(intArrayOf(1, 2, 3, 4).filter { it % 2 == 0 }); println(intArrayOf(1, 2, 3).map { it * 2 }.toIntArray().toList())
}
